import json
import argparse
import os
from pathlib import Path
from typing import Dict, List, Tuple, Optional, Any


def load_training_data_json(run_id: str) -> Dict[str, Any]:
    """Load training data from the JSON file generated by analysis."""
    json_path = os.path.join("evals", run_id, "analysis", "BoN", "training_data.json")
    try:
        with open(json_path, "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: training_data.json not found at {json_path}")
        return {}
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {json_path}")
        return {}


def filter_by_improvement_rate(
    data: Dict[str, Any], threshold: float = 1.0
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Filter data by improvement rate.
    Returns (filtered_data, high_improvement_data)
    """
    filtered_data = {}
    high_improvement_data = {}

    for key, item in data.items():
        improvement_rate = item.get("improvement_rate", 0.0)
        if improvement_rate >= threshold:
            high_improvement_data[key] = item
        else:
            filtered_data[key] = item

    return filtered_data, high_improvement_data


def mark_replay_items(
    current_data: Dict[str, Any], prev_run_dataset, replay_mode: str
) -> Dict[str, Any]:
    """Mark items as replay or frontier based on previous run data."""
    prev_data = prev_run_dataset  # load_training_data_json(prev_run_id)

    # Create a set of keys that had improvement_rate > 0 in previous run
    replay_keys = set()
    for key, item in prev_data.items():
        if item.get("improvement_rate", 0.0) > 0:
            replay_keys.add(key)

    # Mark current items
    for key, item in current_data.items():
        if key in replay_keys:
            item["split"] = "replay"  # i.e. if it was solved in the previous run

            if replay_mode == "join":
                prev_valid_samples = prev_data[key].get("valid_samples", [])
                prev_invalid_samples = prev_data[key].get("invalid_samples", [])
                item["valid_samples"] = sorted(
                    item["valid_samples"] + prev_valid_samples,
                    key=lambda x: x["delta"],
                    reverse=True,
                )
                item["invalid_samples"] = item["invalid_samples"] + prev_invalid_samples

            elif replay_mode == "replace":
                prev_valid_samples = prev_data[key].get("valid_samples", [])
                prev_invalid_samples = prev_data[key].get("invalid_samples", [])
                item["valid_samples"] = sorted(
                    prev_valid_samples, key=lambda x: x["delta"], reverse=True
                )
                item["invalid_samples"] = prev_invalid_samples
            else:
                pass

        else:
            item["split"] = "frontier"

    # return current_data
    output = current_data

    additional_replay_items = {}
    for key in list(replay_keys - set(current_data.keys())):
        prev_data[key]["split"] = "frontier"
        additional_replay_items[key] = prev_data[key]
    print(f"Found {len(list(additional_replay_items.keys()))} additional replay items")

    if replay_mode == "join" or replay_mode == "replace":
        output.update(additional_replay_items)

    return output


def adjust_replay_proportion(
    data: Dict[str, Any],
    high_improvement_data: Dict[str, Any],
    replay_buffer_split: float,
) -> Dict[str, Any]:
    """
    Adjust the proportion of replay items to match replay_buffer_split.
    """
    if not data:
        return data

    # Count current replay and frontier items
    replay_count = sum(1 for item in data.values() if item.get("split") == "replay")
    frontier_count = sum(1 for item in data.values() if item.get("split") == "frontier")
    total_count = len(data)

    if total_count == 0:
        return data

    current_proportion = replay_count / total_count
    target_proportion = replay_buffer_split

    print(
        f"Current replay proportion: {current_proportion:.3f}, Target: {target_proportion:.3f}"
    )

    if current_proportion > target_proportion:
        # Too many replay items, remove some
        replay_items = [(k, v) for k, v in data.items() if v.get("split") == "replay"]
        target_replay_count = int(total_count * target_proportion)
        items_to_remove = replay_count - target_replay_count

        # Remove replay items (keep the ones with higher improvement rates)
        replay_items.sort(key=lambda x: x[1].get("improvement_rate", 0.0), reverse=True)
        for i in range(items_to_remove):
            if i < len(replay_items):
                del data[replay_items[i][0]]

    elif current_proportion < target_proportion:
        # Too few replay items, add from high_improvement_data
        target_replay_count = int(total_count * target_proportion)
        items_to_add = target_replay_count - replay_count

        # Sort high_improvement_data by improvement_rate (ascending) to add lowest ones
        sorted_high_items = sorted(
            high_improvement_data.items(),
            key=lambda x: x[1].get("improvement_rate", 0.0),
        )

        for i in range(min(items_to_add, len(sorted_high_items))):
            key, item = sorted_high_items[i]
            item["split"] = "replay"
            data[key] = item

    return data


def create_sft_dataset(
    data: Dict[str, Any], thinking: bool = False
) -> List[Dict[str, str]]:
    """Create SFT dataset in Alpaca format."""
    dataset = []

    for key, item in data.items():
        # choose top num_samples samples
        champion = item["valid_samples"][0]

        if champion["output"] is None:
            continue

        output_text = (
            champion["cot_output"]
            if thinking
            else "<IMPROVED>\n" + champion["output"] + "\n</IMPROVED>"
        )
        if output_text is None:
            continue

        dataset.append(
            {
                "instruction": item["prompt"],
                # "input": "",
                "output": output_text,
            }
        )

    return dataset


from collections import defaultdict
import math


def softmax(scores, tau=1.0):
    # Compute softmax with temperature tau
    if tau == 0:
        # Avoid division by zero, treat as argmax
        max_idx = scores.index(max(scores))
        return [1.0 if i == max_idx else 0.0 for i in range(len(scores))]
    exp_scores = [math.exp(s / tau) for s in scores]
    total = sum(exp_scores)
    return [e / total for e in exp_scores]


def group_and_weight_by_key(deduped_dataset, tau=1.0, top_k=-1, epsilon=0.01):
    # Group items by key
    grouped = defaultdict(list)
    for item in deduped_dataset:
        grouped[item["key"]].append(item)
    # For each group, compute softmax weights and add to items
    for key, items in grouped.items():
        scores = [item["score"] for item in items]
        weights = softmax(scores, tau)
        for item, w in zip(items, weights):
            item["weight"] = w  # / len(list(grouped.keys()))

        trimmed_items = [item for item in items if item["weight"] > epsilon]
        rest_items = [item for item in items if item["weight"] <= epsilon]

        if top_k > 0:
            # Sort by weight and take top_k items
            trimmed_items.sort(key=lambda x: x["weight"], reverse=True)
            trimmed_items = trimmed_items[:top_k]
            rest_items = rest_items + trimmed_items[top_k:]

        for item in rest_items:
            item["weight"] = 0.0
        new_weights = softmax([item["weight"] for item in trimmed_items], tau)

        for item, w in zip(trimmed_items, new_weights):
            item["weight"] = w

    # Flatten back to a list
    return [item for items in grouped.values() for item in items]


def filter_high_variance(dataset, threshold: float):
    grouped_dataset = defaultdict(list)
    for i, item in enumerate(dataset):
        grouped_dataset[item["key"]].append((i, item))

    variances = {}
    for key, items in grouped_dataset.items():
        scores = [item[1]["score"] for item in items]
        if len(scores) > 1:
            mean_score = sum(scores) / len(scores)
            variance = sum((s - mean_score) ** 2 for s in scores) / (len(scores) - 1)
            variances[key] = variance
        else:
            variances[key] = 0.0

    all_data = [(key, items, variances[key]) for key, items in grouped_dataset.items()]
    all_data.sort(key=lambda x: x[2])
    all_data = all_data[
        : int(len(all_data) * threshold)
    ]  # i.e. get the bottom x% of items by variance
    new_dataset_raw = []
    for key, items, variance in all_data:
        new_dataset_raw.extend(items)
    new_dataset = [item for _, item in sorted(new_dataset_raw, key=lambda x: x[0])]
    return new_dataset

