def create_weighted_sft_dataset(
    data: Dict[str, Any],
    thinking: bool = False,
    tau: float = 1.0,
    num_samples: int = 1,
    epsilon: float = 0.1,
    variance_threshold: float = 0.8,  # get rid of the top x% of items in order of variance of new (correct) scores.
) -> List[Dict[str, Any]]:
    """Create weighted SFT dataset with scores."""
    dataset = []

    for key, item in data.items():
        samples = item["valid_samples"]

        unique_samples = []
        # Deduplicate samples by the "output" attribute
        seen_outputs = set()
        for s in samples:
            out = s.get("output")
            if out is not None and out not in seen_outputs:
                unique_samples.append(s)
                seen_outputs.add(out)

        # Make a list of samples taken from the samples array uniformly spaced with total length num_samples,
        # in the same order, and always including the element at index 0.
        if not unique_samples:
            selected_samples = []
        # elif num_samples >= len(unique_samples) or num_samples == -1:
        else:
            selected_samples = list(unique_samples)
        # else:
        #     # Always include index 0, then select the rest uniformly spaced
        #     indices = [0]
        #     if num_samples > 1:
        #         step = (len(unique_samples) - 1) / (num_samples - 1)
        #         indices += [round(i * step) for i in range(1, num_samples)]
        #     selected_samples = [
        #         unique_samples[i] for i in indices if i < len(unique_samples)
        #     ]

        # Include all samples except invalid
        for sample in selected_samples:

            output_text = (
                sample["cot_output"]
                if thinking
                else "<IMPROVED>\n" + sample["output"] + "\n</IMPROVED>"
            )
            if output_text is None:
                continue

            dataset.append(
                {
                    "key": key,
                    "instruction": item["prompt"],
                    # "input": "",
                    "output": output_text,
                    "score": sample["delta"] if sample["delta"] is not None else 0.0,
                }
            )
    # Deduplicate the dataset by output_text before returning
    # seen_outputs = set()
    # deduped_dataset = []
    # for item in dataset:
    #     output_text = (item["key"],item["output"])
    #     if output_text not in seen_outputs:
    #         deduped_dataset.append(item)#{k:v for k,v in item.items() if k!="key"})
    #         seen_outputs.add(output_text)

    # Group dataset by key
    new_dataset = (
        filter_high_variance(dataset, variance_threshold)
        if variance_threshold > 0
        else dataset
    )

    weighted_dataset_raw = group_and_weight_by_key(
        new_dataset, tau, num_samples, epsilon
    )

    weighted_dataset = [
        {k: v for k, v in item.items() if k != "score" and k != "key"}
        for item in weighted_dataset_raw
        if item["weight"] > 0.0
    ]
    print(f"Filtering out {len(new_dataset)-len(weighted_dataset)} low-weight items")

    return weighted_dataset


def create_dpo_dataset(
    data: Dict[str, Any],
    thinking: bool = False,
    num_samples: int = 1,
    num_invalid: int = 2,
    max_champions: int = 3,
    reject_valid: bool = False,  # idea is that if this is true, we reject all other valid samples as well: may overlap/double count if max_champions>1.
    min_gap: float = 0.0,  # (require delta > min_gap for valid)
) -> List[Dict[str, str]]:
    """Create DPO preference pairs dataset."""
    dataset = []

    for key, item in data.items():

        valid_og = item["valid_samples"]
        invalid_og = item["invalid_samples"]
        valid_filtered, invalid_filtered = [], []
        for valid in valid_og:
            if valid["delta"] is None or valid["delta"] <= min_gap:
                invalid_filtered.append(valid)
            else:
                valid_filtered.append(valid)
        invalid_filtered += invalid_og

        invalid_samples = invalid_filtered  # item["invalid_samples"]
        # Deduplicate invalid_samples by output
        unique_invalid_samples = []
        seen_invalid_outputs = set()
        for invalid in invalid_samples:
            output = invalid.get("output")
            if output is not None and output not in seen_invalid_outputs:
                unique_invalid_samples.append(invalid)
                seen_invalid_outputs.add(output)

        if num_invalid >= 0:
            invalids = (
                unique_invalid_samples[:num_invalid] if unique_invalid_samples else []
            )
        else:
            invalids = unique_invalid_samples

        valid_samples = sorted(
            valid_filtered,
            key=lambda x: x.get("delta", float("-inf")),
            reverse=True,
        )
        # Deduplicate valid_samples by delta value
        unique_valid_samples = []
        seen_deltas = set()
        for sample in valid_samples:
            delta = sample.get("delta")
            if delta is not None and delta not in seen_deltas:
                unique_valid_samples.append(sample)
                seen_deltas.add(delta)
        valids = unique_valid_samples

        if max_champions >= 0:
            rng = min(max_champions, len(valids))
        else:
            rng = len(valids)

        for i in range(rng):

            samples = valids[i + 1 :]

            champion = valids[i]

            champion_text = (
                champion["cot_output"]
                if thinking
                else "<IMPROVED>\n" + champion["output"] + "\n</IMPROVED>"
            )
            if champion_text is None:
                continue

            unique_samples = []
            # Deduplicate samples by the "output" attribute
            seen_outputs = set([champion.get("delta")])
            for s in samples:
                # out = s.get("output")
                delta = s.get("delta")
                if delta is not None and delta not in seen_outputs:
                    unique_samples.append(s)
                    seen_outputs.add(delta)

            # Make a list of samples taken from the samples array uniformly spaced with total length num_samples,
            # in the same order, and always including the element at index 0.
            if not unique_samples:
                selected_samples = []
            elif num_samples >= len(unique_samples) or num_samples == -1:
                selected_samples = list(unique_samples)
            else:
                # Always include index 0, then select the rest uniformly spaced
                indices = [0]
                if num_samples > 1:
                    step = (len(unique_samples) - 1) / (num_samples - 1)
                    indices += [round(i * step) for i in range(1, num_samples)]

                selected_samples = [
                    unique_samples[i] for i in indices if i < len(unique_samples)
                ]

            # Create pairs with all other samples
            for sample in selected_samples:

                rejected_text = (
                    sample["cot_output"]
                    if thinking
                    else "<IMPROVED>\n" + sample["output"] + "\n</IMPROVED>"
                )
                if rejected_text is None:
                    continue

                if sample["delta"] is not None and sample["delta"] >= champion["delta"]:
                    continue

                dataset.append(
                    {
                        "prompt": item["prompt"],
                        "chosen": champion_text,
                        "rejected": rejected_text,
                    }
                )

            possible_valids_with_invalids = invalids
            if reject_valid:
                possible_valids_with_invalids = selected_samples + invalids

            for invalid in possible_valids_with_invalids:
                dataset.append(
                    {
                        "prompt": item["prompt"],
                        "chosen": champion_text,
                        "rejected": (
                            invalid["cot_output"]
                            if thinking
                            else "<IMPROVED>\n" + invalid["output"] + "\n</IMPROVED>"
                        ),
                    }
                )

    return dataset


def save_jsonl(dataset: List[Dict[str, Any]], output_path: str):
    """Save dataset to JSONL format."""
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    try:
        with open(output_path, "w", encoding="utf-8") as f:
            for item in dataset:
                f.write(json.dumps(item, ensure_ascii=False) + "\n")
        print(f"Saved {len(dataset)} items to {output_path}")
    except Exception as e:
        print(f"Error saving to {output_path}: {e}")


def generate_specified_dataset(run_id, args, prev_run_dataset=None) -> Dict[str, Any]:

    # Load training data
    data = load_training_data_json(run_id)
    if not data:
        print("No training data found. Exiting.")
        return {}

    print(f"Loaded {len(data)} items from training data")

    # Filter out items with improvement_rate <= 0
    data = {k: v for k, v in data.items() if v.get("improvement_rate", 0.0) > 0}
    print(f"After filtering improvement_rate > 0: {len(data)} items")

    if prev_run_dataset and args.replay_buffer_split is not None:
        data = mark_replay_items(data, prev_run_dataset, args.replay_type)  # ADD ARGS
        replay_count = sum(1 for item in data.values() if item.get("split") == "replay")
        frontier_count = sum(
            1 for item in data.values() if item.get("split") == "frontier"
        )
        print(f"Marked items - Replay: {replay_count}, Frontier: {frontier_count}")

    # Filter by improvement rate threshold
    data, high_improvement_data = filter_by_improvement_rate(
        data, args.filter_threshold
    )
    print(
        f"After filtering improvement_rate < {args.filter_threshold}: {len(data)} items"
    )
    print(f"High improvement items set aside: {len(high_improvement_data)} items")

    # Adjust replay proportion if needed
    if prev_run_dataset and args.replay_buffer_split is not None:
        data = adjust_replay_proportion(
            data, high_improvement_data, args.replay_buffer_split
        )
        replay_count = sum(1 for item in data.values() if item.get("split") == "replay")
        frontier_count = sum(
            1 for item in data.values() if item.get("split") == "frontier"
        )
        print(
            f"After replay adjustment - Replay: {replay_count}, Frontier: {frontier_count}"
        )
    return data


def main(args):
    # run_id: str, output_path: Optional[str] = None, thinking: bool = False,
    #      filter_threshold: float = 1.0, prev_run_id: Optional[str] = None,
    #      replay_buffer_split: Optional[float] = None, training_type: str = "sft",
    #      tau: float = 1.0, num_samples:int = 1):
    """
    Generate training dataset from analysis results.

    Args:
        run_id: Identifier for the run
        output_path: Output path for the JSONL file (default: evals/run_id/analysis/BoN/training_data.jsonl)
        thinking: Whether to use CoT output (default: False)
        filter_threshold: Threshold for filtering high improvement rate items (default: 1.0)
        prev_run_id: Previous run ID for replay buffer (default: None)
        replay_buffer_split: Target proportion of replay items (default: None)
        training_type: Type of training dataset (sft, weighted_sft, dpo) (default: sft)
    """

    # Set default output path
    if args.output_path is None:
        print(args.run_id)
        args.output_path = os.path.join(
            "evals", args.run_id, "analysis", "BoN", "training_data.jsonl"
        )

    past_run_ids = [
        item.strip()
        for item in (args.prev_run_id.split(",") if args.prev_run_id else [])
    ]

    final_dataset = []
    if len(past_run_ids) > 0:
        prev_run_id = past_run_ids[0]
        prev_run_dataset = load_training_data_json(prev_run_id)

        for current_run_id in past_run_ids[1:] + [args.run_id]:
            print(
                f"Generating dataset for run {current_run_id} with replay from {prev_run_id}"
            )
            print(type(prev_run_dataset))
            dataset = generate_specified_dataset(current_run_id, args, prev_run_dataset)
            prev_run_dataset = dataset
            prev_run_id = current_run_id

        final_dataset = prev_run_dataset
    else:
        final_dataset = generate_specified_dataset(args.run_id, args)

    postprocessed_dataset = []

    # Create dataset based on training type
    if args.type == "sft":
        postprocessed_dataset = create_sft_dataset(final_dataset, args.thinking)
    elif args.type == "weighted_sft":
        postprocessed_dataset = create_weighted_sft_dataset(
            final_dataset,
            args.thinking,
            args.tau,
            args.num_samples,
            args.epsilon,
            args.variance_threshold,
        )
    elif args.type == "dpo":
        postprocessed_dataset = create_dpo_dataset(
            final_dataset,
            args.thinking,
            args.num_samples,
            args.num_invalid,
            args.max_champions,
            args.reject_valid,
            args.min_gap,
        )
    else:
        print(f"Unknown training type: {args.type}")
        postprocessed_dataset = []

    save_jsonl(postprocessed_dataset, args.output_path)
    return postprocessed_dataset

    # proceed to build the dataset in pairs (prev_run_replay_dataset, current_run_id)
