def get_parser():
    parser = argparse.ArgumentParser(
        description="Generate training dataset from analysis results."
    )
    parser.add_argument("run_id", help="Identifier for the run.")
    parser.add_argument(
        "--output_path",
        default=None,
        help="Output path for JSONL file (default: evals/[run_id]/analysis/BoN/training_data.jsonl)",
    )
    parser.add_argument(
        "--thinking",
        action="store_true",
        help="Use CoT output instead of regular output (default: False)",
    )
    parser.add_argument(
        "--filter_threshold",
        type=float,
        default=1.0,
        help="Threshold for filtering high improvement rate items (default: 1.0)",
    )
    parser.add_argument(
        "--prev_run_id",
        default=None,
        help="Previous run ID(s) for replay buffer (default: []) -> give as comma separated list: base,iter1,iter2,...",
    )
    parser.add_argument(
        "--replay_buffer_split",
        type=float,
        default=None,
        help="Target proportion of replay items (default: None)",
    )
    parser.add_argument(
        "--type",
        choices=["sft", "weighted_sft", "dpo"],
        default="sft",
        help="Type of training dataset (default: sft)",
    )
    parser.add_argument(
        "--tau", default=1.0, type=float, help="temperature value for weighted SFT"
    )
    parser.add_argument(
        "--num_samples",
        default=-1,
        type=int,
        help="Number of samples to include (weighted SFT ignores invalid, DPO gets 1 invalid) (-1 means all)",
    )
    parser.add_argument(
        "--replay_type",
        default=None,
        help='Type of replay buffer (default: None; choices: ["join","replace", None])',
        choices=["join", "replace", None],
    )
    parser.add_argument(
        "--num_invalid",
        default=1,
        type=int,
        help="Number of invalid samples (default: 1)",
    )
    parser.add_argument(
        "--max_champions",
        default=1,
        type=int,
        help="Maximum number of champions (default: 1)",
    )
    parser.add_argument(
        "--reject_valid",
        action="store_true",
        help="Reject all valid samples if this is true (default: False)",
    )
    parser.add_argument(
        "--min_gap",
        default=0.0,
        type=float,
        help="Minimum gap required for valid samples (default: 0.0)",
    )

    parser.add_argument(
        "--epsilon",
        default=0.0,
        type=float,
        help="Epsilon value for exploration (default: 0.0)",
    )
    parser.add_argument(
        "--variance_threshold",
        default=1.0,
        type=float,
        help="(Max) Variance threshold for filtering (default: 1.0)",
    )

    return parser


if __name__ == "__main__":
    parser = get_parser()
    args = parser.parse_args()
    main(args)  # .run_id, args.output_path, args.thinking, args.filter_threshold,
